using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Demo6.Game;
public static class UiArtExport {
 const string Source="아트/UI-정리-v1/아이콘-원본";
 static void Save(Texture tex,string path,int divisor=1){Directory.CreateDirectory(Path.GetDirectoryName(path));var old=RenderTexture.active;var rt=RenderTexture.GetTemporary(tex.width/divisor,tex.height/divisor,0,RenderTextureFormat.ARGB32,RenderTextureReadWrite.sRGB);Texture2D read=null;try{Graphics.Blit(tex,rt);RenderTexture.active=rt;read=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false);read.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);read.Apply();File.WriteAllBytes(path,read.EncodeToPNG());}finally{RenderTexture.active=old;if(read)UnityEngine.Object.DestroyImmediate(read);RenderTexture.ReleaseTemporary(rt);}}
 public static object Build(){if(EditorApplication.isPlaying)throw new Exception("Stop Play first");var list=new List<object>();foreach(var id in ItemIconArt.Ids){for(int layer=-1;layer<2;layer++){var sprite=ItemIconArt.Build(id,512,layer);string file=Source+"/"+(layer<0?"PNG/":"layers/")+id+(layer<0?"":layer==0?"-main":"-detail")+".png";Save(sprite.texture,file);if(layer<0)Save(sprite.texture,"Assets/Resources/UI/Items/"+id+".png",2);UnityEngine.Object.DestroyImmediate(sprite.texture);UnityEngine.Object.DestroyImmediate(sprite);}list.Add(new{id,master=1024,game=512,layers=2});}AssetDatabase.Refresh();foreach(var id in ItemIconArt.Ids){string p="Assets/Resources/UI/Items/"+id+".png";var ti=(TextureImporter)AssetImporter.GetAtPath(p);ti.textureType=TextureImporterType.Default;ti.alphaIsTransparency=true;ti.mipmapEnabled=false;ti.filterMode=FilterMode.Bilinear;ti.textureCompression=TextureImporterCompression.Uncompressed;ti.maxTextureSize=1024;ti.SaveAndReimport();}string json=Newtonsoft.Json.JsonConvert.SerializeObject(list,Newtonsoft.Json.Formatting.Indented);File.WriteAllText(Source+"/manifest.json",json);return json;}
}
